// Error Handler - ضع هذا كأول node بعد الـ Trigger
try {
  const message = $input.first().json;

  // التحقق من وجود البيانات الأساسية
  if (!message || !message.text || !message.chat) {
    throw new Error('بيانات الرسالة غير مكتملة');
  }

  // تنظيف النص المدخل
  const cleanText = message.text.trim().replace(/[^\w\u0600-\u06FF\s]/g, '');

  if (cleanText.length < 2) {
    throw new Error('النص قصير جداً');
  }

  return [{ 
    json: {
      originalMessage: message,
      cleanedText: cleanText,
      chatId: message.chat.id,
      timestamp: new Date().toISOString(),
      error: null
    }
  }];

} catch (error) {
  // تسجيل الخطأ وإرسال رسالة للعميل
  return [{
    json: {
      error: error.message,
      chatId: $input.first().json.chat?.id,
      errorType: 'VALIDATION_ERROR',
      timestamp: new Date().toISOString()
    }
  }];
}
