// Google Sheets Reader - Function Node
async function fetchProducts() {
  try {
    const sheetData = await $node["Google Sheets"].execute();

    if (!sheetData || sheetData.length === 0) {
      throw new Error('لا توجد بيانات في الجدول');
    }

    const products = sheetData.map(row => ({
